        ('except ImportError:  # the maths can be tested outside of Maya', 'If Maya is not available (plain Python, tests), the names are set to `None` instead of crashing, so the pure math functions can still be imported.'),
        ('from PySide6 import QtCore, QtWidgets', 'Fallback for newer Maya versions that ship PySide6 instead of PySide2.'),
        ('long = int', 'Python 3 has no `long` type. Defining it as `int` lets the same code (`long(ptr)`) run on Python 2 and 3.'),
        ('if n > 0.05 * spread:', 'Net travel is meaningful only if it is bigger than 5% of the motion\'s size; otherwise use the main axis.'),
        ('angle = 0.5 * math.atan2(2.0 * sxz, sxx - szz)', 'The angle of the main axis of a 2D point cloud (principal component), from the spread in X (`sxx`), in Z (`szz`) and together (`sxz`).'),
        ('return sum((t - mt) * (v - mv) for t, v in zip(times, values)) / den', 'Least-squares slope: covariance of time and value divided by the variance of time.'),
        ('[(p[0] - p0[0]) * forward[0] + (p[2] - p0[2]) * forward[1]', 'Distance travelled along the forward direction: the dot product of (point - first point) with the forward vector.'),
        ('travel = [speed * (t - t0) for t in times]', 'Average mode: replace the real travel with a straight line at the average speed. Only this straight line is cancelled.'),
        ('out[t][i] -= d * axis[i]', 'Minus: the offset is the **opposite** of the travel.'),
